architecture.h4_f:
msg = CBOR{v: 1, teacsa, freagairt_to, chuir_at}
ct = AES-GCM-256-Encrypt(k, nonce, msg, aad=room_id)
POST / api/rooms/{id}/messages {ciphertext: hex(ct), nonce: hex}

cryptoWire.h1_f:
pt = CBOR{v: 1, teacsa, reply_to ?, thread_id ?, iomradh ?, sent_at}
ct = AES-GCM-256-Encrypt(room_key, nonce, pt, aad = hex(room_id))
sreang = CBOR{
  v: 1,
  ciphertext: hex(ct), // fad caochlaideach
  nonce: heics (12 B),
  sender_pseudo: hex(16 B),
  sent_at: unix_ms
}

cryptoWire.h5_f:
a-muigh = CBOR{
  source_node: hex32,
  target_user: int64,
  inner_ciphertext: bytes,
  inner_nonce: bytes,
  sent_at: unix_ms
}
sig = Ed25519-Sign (source_priv, taobh a-muigh)
POST / caidreachas/lìbhrigeadh { cèis: taobh a-muigh, sig: hex64 }

auth.h1_f:
POST /api/dearbhadh/clàradh
  { ainm-cleachdaidh, facal-faire, x25519_public_key, display_name, fòn?, post-d?, avatar_emoji }

Freagairt 201 air a chruthachadh:
  { access_token, refresh_token, user_id, ainm-cleachdaiche, ... }

auth.h3_f:
access_token pàighidh pàighidh:
  { sub: user_id, jti: device_id, seòrsa: "ruigsinneachd", exp: a-nis + 15min }
ùrachadh_token pàighidh pàighidh:
  { sub: user_id, jti: device_id, seòrsa: "ùrachadh", exp: a-nis + 30d }

HS256 air a shoidhnigeadh le dìomhaireachd 64-byte nód bho .env

auth.h4_f:
register_begin(): dùbhlan = rand(32)
                    roghainnean = { rp.id, user.id, pubKeyCredParams, dùbhlan }
                    roghainnean tilleadh

register_finish(teisteanas):
  dearbhaich fianais an aghaidh TPM / Secure Enclave root CA
  stòr { credential_id, public_key, cuntair: 0 }

auth.h7_f:
POST /api/authentication/qr/tòiseachadh
  → { nonce: hex 128-bit, ttl: 60 }
QR payload = { nonce, user_id, frithealaiche: "https://node.example" }

POST /api/authentication/qr/verify { nonce }
  → inneal ùr clàraichte; Thill JWTs.

rooms.h6_f:
sender_pseudo = HMAC-SHA256 (seòmar_pseudo_salt, sender_id) [: 16] // 32 hex
ciphertext = AES-GCM-Encrypt(room_key, nonce, CBOR_payload, aad=room_id)

Frèam fan-a-mach: { seòrsa: "m", seòmar, msg: {id, ct, nonce, sender_pseudo, sent_at} }

files.h2_f:
init POST / api/files/resumable/init {ainm faidhle, meud, chunk_size_hint}
            ← {upload_id, chunk_size}
pìos PUT /api/files/resumable/{upload_id}/chunk/{offset} <ct bytes>
            ← 204
cuir crìoch air POST /api/files/resumable/{upload_id}/finalise {plain_blake3}
            ← 201 {faidhle_id, url}
TTL air neo-chrìochnach: 24 h

files.h4_f:
àicheadh_list = {
  "iarrtas/x-dosexec",
  "app/x-sharedlib",
  "app/x-mach-binary",
}
ma tha magic.from_buffer (buf [: 1024]) ann an deny_list: till 415

presence.h1_f:
neach-dèiligidh: air a' chiad bhuille-iuchrach → cuir {type: "t", stàite: "tòiseachadh"}
         cha chuirear tuilleadh airson 3 s mur atharraich an staid
         10 diogan às deidh buille-iuchrach mu dheireadh → cuir {type:" t", stà: "stad"}
cuidhteas: stad fèin-ghluasadach 10 diog às deidh an “tòiseachadh” mu dheireadh mura do ràinig “stad”.

